/* İlim dersleri: her ilimde sırayla açılan dersler. Kur'an âyetleri doğrulanmış metinden (Tanzil) yüklenir. */
const ILIMLER=[{"id": "arapca", "ad": "Arapça", "cat": "ilim", "kisa": "Kur'an'ın ve namazın dilini harf harf öğren.", "dersler": [{"id": "ar1", "sev": "Başlangıç", "t": "Arap alfabesine giriş", "dk": 5, "bl": [{"p": "Arapça sağdan sola yazılır ve okunur. Alfabe 28 harften oluşur; hemze ise ayrıca bir işaretle yazılır."}, {"p": "Harflerin çoğu kelimedeki yerine göre (başta, ortada, sonda ya da tek başına) biraz şekil değiştirir. Altı harf kendinden sonraki harfe bitişmez: ا د ذ ر ز و"}, {"h": "Harekeler"}, {"list": ["Üstün (fetha): harfin üstüne konan küçük çizgi; “e” ya da “a” sesi verir.", "Esre (kesra): harfin altına konan çizgi; “i” sesi verir.", "Ötre (damme): harfin üstündeki küçük vav işareti; “u” ya da “ü” sesi verir.", "Cezm (sükûn): harfi harekesiz okutur, örneğin “bis” hecesindeki “s”.", "Şedde: harfi iki kez okutur; örneğin “Allah” kelimesindeki “ll”."]}, {"ar": "بِسْمِ اللَّهِ", "ok": "Bismillâh", "tr": "Allah'ın adıyla.", "src": "Besmele"}, {"p": "Bu iki kelimede: ب esre ile “bi”, س cezm ile “s”, م esre ile “mi” okunur; ل harfindeki şedde “ll” sesini verir."}], "oz": ["Arapça sağdan sola yazılır; 28 harf vardır.", "ا د ذ ر ز و harfleri sonraki harfe bitişmez.", "Üstün “e/a”, esre “i”, ötre “u/ü” sesi verir; cezm harekesiz okutur, şedde ikiler."], "test": [{"s": "Arapça hangi yönde yazılır?", "c": ["Yukarıdan aşağı", "Sağdan sola", "Soldan sağa"], "d": 1, "a": "Arapça sağdan sola yazılır ve okunur."}, {"s": "Esre harekesi hangi sesi verir?", "c": ["e / a", "u / ü", "i"], "d": 2, "a": "Esre harfin altına konur ve “i” sesi verir."}, {"s": "Şedde ne işe yarar?", "c": ["Harfi uzatır", "Harfi iki kez okutur", "Harfi okutmaz"], "d": 1, "a": "Şedde harfi ikizleştirir; “Allah” kelimesindeki “ll” gibi."}, {"s": "Hangisi kendinden sonraki harfe bitişmez?", "c": ["ب", "ر", "م"], "d": 1, "a": "ر harfi sonraki harfe bitişmeyen altı harften biridir."}], "uygula": "Bugün Fâtiha'nın ilk âyetinde üstün, esre ve ötreleri tek tek bulmayı dene."}, {"id": "ar3", "sev": "Başlangıç", "t": "Benzer harfler ve noktalar", "dk": 5, "bl": [{"p": "Arap alfabesinde bazı harfler aynı gövdeye sahiptir; onları birbirinden ayıran noktalardır. Noktanın yeri ve sayısı harfi değiştirir."}, {"list": ["ب (be) altında bir nokta, ت (te) üstünde iki nokta, ث (se) üstünde üç nokta", "ج (cim) içinde bir nokta, ح (ha) noktasız, خ (hı) üstünde bir nokta", "د (dal) noktasız, ذ (zel) üstünde bir nokta", "ر (ra) noktasız, ز (ze) üstünde bir nokta", "س (sin) noktasız, ش (şın) üstünde üç nokta", "ص (sad) noktasız, ض (dad) üstünde bir nokta", "ط (tı) noktasız, ظ (zı) üstünde bir nokta", "ع (ayın) noktasız, غ (ğayın) üstünde bir nokta", "ف (fe) üstünde bir nokta, ق (kaf) üstünde iki nokta"]}, {"not": "Okurken önce harfin gövdesine, sonra noktalarına bak. Nokta hatası kelimenin anlamını değiştirebilir."}], "oz": ["Noktalar benzer harfleri birbirinden ayırır.", "ب ت ث aynı gövdeli; noktaların sayısı ve yeri farklı.", "ف bir, ق iki noktalıdır."], "test": [{"s": "Üstünde iki nokta olan harf hangisidir?", "c": ["ب", "ت", "ث"], "d": 1, "a": "ت (te) harfinin üstünde iki nokta vardır."}, {"s": "ج ح خ harflerinden hangisi noktasızdır?", "c": ["خ", "ح", "ج"], "d": 1, "a": "ح (ha) noktasızdır."}, {"s": "ف ile ق arasındaki fark nedir?", "c": ["ق noktasız", "İkisi de aynı harf", "ف bir, ق iki noktalı"], "d": 2, "a": "ف üstünde bir, ق üstünde iki nokta taşır."}], "uygula": "Bugün Fâtiha'da noktalı harfleri bul ve hangi harf olduklarını söyle."}, {"id": "ar2", "sev": "Orta", "t": "Namazda okuduklarımızı anlayalım: Fâtiha", "dk": 6, "bl": [{"p": "Fâtiha'yı her rekâtta okuyoruz. Kelimelerin anlamını bilmek okurken kalbin de katılmasını kolaylaştırır."}, {"h": "Kelime kelime"}, {"list": ["الْحَمْدُ (el-hamdü): hamd, övgü ve şükür", "لِلَّهِ (lillâhi): Allah'a ait, Allah içindir", "رَبِّ (Rabbi): Rabbi; terbiye eden, yetiştiren", "الْعَالَمِينَ (el-âlemîn): âlemler, bütün varlıklar", "مَالِكِ (mâliki): sahibi", "يَوْمِ الدِّينِ (yevmi'd-dîn): hesap ve ceza günü", "إِيَّاكَ (iyyâke): yalnız sana", "نَعْبُدُ (na'büdü): ibadet ederiz", "نَسْتَعِينُ (neste'în): yardım dileriz", "اهْدِنَا (ihdinâ): bize doğru yolu göster, bizi ilet", "الصِّرَاطَ الْمُسْتَقِيمَ (es-sırâta'l-müstakîm): dosdoğru yol", "الْمَغْضُوبِ (el-mağdûbi): gazaba uğramış", "الضَّالِّينَ (ed-dâllîn): yoldan sapmışlar"]}, {"h": "Küçük bir dil bilgisi"}, {"list": ["“el-” takısı kelimeyi belirli yapar: “el-hamdü” yani “hamd”.", "Bazı harflerden önce “el-” takısındaki “l” okunmaz, sonraki harf ikizleşir: “er-Rahmân”, “ed-dîn”. Bu harflere şemsî (güneş) harfleri denir.", "“-nâ” eki “biz, bizi” anlamı katar: ihdinâ, “bizi ilet”.", "“-ke” eki “sen, seni” anlamı katar: iyyâke, “yalnız sana”."]}, {"q": ["1:5"], "src": "Fâtiha 1/5"}], "oz": ["Fâtiha'da hamd, Allah'ı tanıma, yalnız O'na kulluk ve doğru yol duası vardır.", "“el-” takısı belirlilik verir; şemsî harflerde “l” okunmaz.", "“-nâ” biz, “-ke” sen anlamı katar."], "test": [{"s": "“رَبِّ” kelimesinin anlamı nedir?", "c": ["Rab", "Yol", "Gün"], "d": 0, "a": "Rab; terbiye eden, yetiştiren, sahibi demektir."}, {"s": "“إِيَّاكَ” kelimesindeki “-ke” eki kimi gösterir?", "c": ["Sen", "Onlar", "Biz"], "d": 0, "a": "“-ke” ikinci tekil şahıstır; iyyâke “yalnız sana” demektir."}, {"s": "“er-Rahmân” derken “el-” takısının “l” sesi neden okunmaz?", "c": ["Kelime fiil olduğu için", "Yazım hatası olduğu için", "“r” şemsî harf olduğu için"], "d": 2, "a": "Şemsî harflerden önce “l” okunmaz, sonraki harf ikizleşir."}, {"s": "“اهْدِنَا” ne demektir?", "c": ["Bizi bağışla", "Bize rızık ver", "Bize doğru yolu göster"], "d": 2, "a": "İhdinâ, “bizi doğru yola ilet” anlamındadır."}], "uygula": "Bugünkü namazlarında Fâtiha'yı okurken her âyetin anlamını içinden düşün."}, {"id": "ar7", "sev": "Orta", "t": "Et-Tahiyyâtü'nün anlamı", "dk": 6, "bl": [{"p": "Namazın oturuşlarında okunan Et-Tahiyyâtü, Hanefîlerin tercih ettiği Abdullah b. Mes'ûd rivayetine göre şöyledir. (Buhârî, Ezan; Müslim, Salât)"}, {"ar": "التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "ok": "Et-tahiyyâtü lillâhi ve's-salavâtü ve't-tayyibât. Es-selâmü aleyke eyyühe'n-nebiyyü ve rahmetullâhi ve berakâtüh. Es-selâmü aleynâ ve alâ ibâdillâhi's-sâlihîn. Eşhedü en lâ ilâhe illallâh ve eşhedü enne Muhammeden abdühû ve rasûlüh.", "tr": "Bütün saygı ve tazimler, dualar ve güzel sözler Allah'a aittir. Ey Peygamber! Selam, Allah'ın rahmeti ve bereketi senin üzerine olsun. Selam bizim üzerimize ve Allah'ın salih kulları üzerine olsun. Şahitlik ederim ki Allah'tan başka ilah yoktur ve yine şahitlik ederim ki Muhammed O'nun kulu ve elçisidir.", "src": "Buhârî, Ezan; Müslim, Salât"}, {"h": "Kelimeler"}, {"list": ["التَّحِيَّاتُ: saygı ve tazimler", "الصَّلَوَاتُ: dualar, namazlar", "الطَّيِّبَاتُ: güzel söz ve ameller", "عِبَادِ اللَّهِ الصَّالِحِينَ: Allah'ın salih kulları", "أَشْهَدُ: şahitlik ederim", "عَبْدُهُ وَرَسُولُهُ: O'nun kulu ve elçisi"]}], "oz": ["Et-Tahiyyâtü oturuşlarda okunur.", "Hanefîler İbn Mes'ûd rivayetini esas alır.", "“Eşhedü” şahitlik ederim demektir."], "test": [{"s": "“التَّحِيَّاتُ” ne demektir?", "c": ["Selam", "Saygı ve tazimler", "Şahitlik"], "d": 1, "a": "Tahiyyât, saygı ve tazim ifadeleridir."}, {"s": "“أَشْهَدُ” kelimesinin anlamı nedir?", "c": ["Bilirim", "Şahitlik ederim", "İman ederim"], "d": 1, "a": "Eşhedü, şahitlik ederim demektir."}, {"s": "“عِبَادِ اللَّهِ الصَّالِحِينَ” kimlerdir?", "c": ["Allah'ın salih kulları", "Melekler", "Peygamberler"], "d": 0, "a": "Allah'ın iyi ve salih kullarıdır."}], "uygula": "Bugün oturuşlarda Et-Tahiyyâtü'yü okurken Peygamberimize selam verdiğini hatırla."}]}, {"id": "tecvid", "ad": "Tecvid", "cat": "kuran", "kisa": "Kur'an'ı harflerin hakkını vererek doğru okumanın kuralları.", "dersler": [{"id": "te1", "sev": "Başlangıç", "t": "Tecvid nedir? Harflerin çıkış yerleri", "dk": 5, "bl": [{"p": "Tecvid sözlükte “güzelleştirmek, bir işi iyi yapmak” demektir. Terim olarak Kur'an'ı her harfin hakkını vererek, kurallarına uygun okumaktır."}, {"q": ["73:4"], "src": "Müzzemmil 73/4"}, {"h": "Mahreç: harfin çıktığı yer"}, {"p": "Her harfin ağızda, boğazda ya da dudakta bir çıkış yeri vardır; buna mahreç denir. Bazı Arap harflerinin sesi Türkçede yoktur, bu yüzden özen ister:"}, {"list": ["ح ve ع: boğazın ortasından çıkar.", "خ ve غ: boğazın ağza en yakın kısmından çıkar.", "ق: dilin kökünden, kalın çıkar; ك ise daha önden, ince çıkar.", "ص ض ط ظ: kalın okunan harflerdendir."]}, {"not": "Benzer harfleri karıştırmak anlamı değiştirebilir: قَلْب (kalb) “kalp”, كَلْب (kelb) ise “köpek” demektir."}], "oz": ["Tecvid, Kur'an'ı harflerin hakkını vererek okumaktır.", "Mahreç, harfin çıktığı yerdir.", "Benzer sesli harfleri karıştırmak anlamı bozabilir."], "test": [{"s": "Tecvid kelimesinin sözlük anlamı nedir?", "c": ["Ezberlemek", "Güzelleştirmek, iyi yapmak", "Tercüme etmek"], "d": 1, "a": "Tecvid sözlükte güzelleştirmek, bir işi iyi yapmak demektir."}, {"s": "Mahreç ne demektir?", "c": ["Harfin çıktığı yer", "Harfin uzatılması", "Harfin yazılışı"], "d": 0, "a": "Mahreç, harfin ağız, boğaz ya da dudaktaki çıkış yeridir."}, {"s": "ق ile ك harflerini ayırt etmek neden önemlidir?", "c": ["Aralarında fark yoktur", "Sadece güzel görünsün diye", "Anlam değişebilir"], "d": 2, "a": "Örneğin kalb (kalp) ile kelb (köpek) farklı kelimelerdir."}], "uygula": "Bugün Fâtiha'yı okurken ح ve ه harflerinin farkına dikkat et."}, {"id": "te3", "sev": "Başlangıç", "t": "Kalın ve ince harfler", "dk": 5, "bl": [{"p": "Bazı harfler ağzı dolduracak şekilde kalın (tefhim), diğerleri ince (terkik) okunur. Kalın harfleri ince okumak, ince harfleri kalınlaştırmak bir okuma hatasıdır."}, {"h": "Her zaman kalın okunan harfler"}, {"p": "خ ص ض غ ط ق ظ. Bunları kolay hatırlamak için “hus da' ğat kız” denir."}, {"h": "Duruma göre değişenler"}, {"list": ["ر (ra): bazen kalın, bazen ince okunur.", "ل (lam): Allah lafzında, öncesine göre kalın ya da ince okunur.", "Elif: kendinden önceki harf kalınsa kalın, inceyse ince okunur."]}, {"not": "Geri kalan harfler ince okunur."}], "oz": ["Kalın harfler: خ ص ض غ ط ق ظ.", "Ra, Allah lafzındaki lam ve elif duruma göre değişir.", "Kalın harfi ince okumak hatadır."], "test": [{"s": "Hangisi her zaman kalın okunan harflerdendir?", "c": ["ك", "ص", "س"], "d": 1, "a": "ص kalın harflerdendir; س incedir."}, {"s": "Kalın harfleri hatırlamak için hangi ifade kullanılır?", "c": ["Kutbu cedd", "Hus da' ğat kız", "Yermelûn"], "d": 1, "a": "Kalın harfler “hus da' ğat kız” ifadesinde toplanır."}, {"s": "Elif nasıl okunur?", "c": ["Her zaman kalın", "Her zaman ince", "Önceki harfe göre"], "d": 2, "a": "Elif kendinden önceki harfe uyar."}], "uygula": "Bugün okurken ص ile س, ط ile ت harflerini ayırt etmeye dikkat et."}, {"id": "te2", "sev": "Orta", "t": "Nûn-i sâkin ve tenvin: İzhar, idgam, iklab, ihfa", "dk": 7, "bl": [{"p": "Harekesiz nûn (نْ) ya da tenvin (iki üstün, iki esre, iki ötre) okunurken, sonra gelen harfe göre dört farklı kural uygulanır."}, {"h": "1. İzhar (açık okuma)"}, {"p": "Sonra boğaz harflerinden biri gelirse nûn açıkça okunur, genizden okunmaz. Boğaz harfleri: ء ه ع ح غ خ. Örnek: مِنْ عِلْمٍ (min ilmin)."}, {"h": "2. İdgam (katarak okuma)"}, {"p": "Sonra ي ر م ل و ن harflerinden biri gelirse (kolay hatırlamak için “yermelûn”), nûn bu harfe katılarak okunur. ي ن م و harflerinde genizden (gunneli), ل ve ر harflerinde gunnesiz okunur. Örnek: مِنْ رَبِّهِمْ (mir-rabbihim)."}, {"h": "3. İklab (çevirme)"}, {"p": "Sonra ب gelirse nûn, “m” sesine çevrilerek genizden okunur. Örnek: مِنْ بَعْدِ (mim ba'di)."}, {"h": "4. İhfa (gizleme)"}, {"p": "Geri kalan 15 harften biri gelirse nûn, izhar ile idgam arasında, gizlenerek ve genizden okunur. Örnek: مِنْ قَبْلِ (min kabli; “n” genizden)."}, {"not": "Bu kurallar en iyi bir hocadan dinleyerek öğrenilir; okuyuşunu bir bilene dinletmen çok faydalıdır."}], "oz": ["Boğaz harfleri gelirse izhar: açık oku.", "“Yermelûn” harfleri gelirse idgam: kat.", "ب gelirse iklab: “m”ye çevir.", "Kalan 15 harfte ihfa: gizle, genizden oku."], "test": [{"s": "Nûn-i sâkinden sonra ع gelirse hangi kural uygulanır?", "c": ["İhfa", "İzhar", "İdgam"], "d": 1, "a": "ع boğaz harfidir; boğaz harflerinde izhar yapılır."}, {"s": "Nûn-i sâkinden sonra ب gelirse ne yapılır?", "c": ["Açık okunur", "“m” sesine çevrilir", "Okunmaz"], "d": 1, "a": "Buna iklab denir: مِنْ بَعْدِ “mim ba'di” okunur."}, {"s": "“Yermelûn” harfleri hangi kurala aittir?", "c": ["İklab", "İzhar", "İdgam"], "d": 2, "a": "ي ر م ل و ن harfleri gelince idgam yapılır."}, {"s": "İhfa kaç harfte yapılır?", "c": ["15", "1", "6"], "d": 0, "a": "İzhar 6, idgam 6, iklab 1 harftir; geri kalan 15 harfte ihfa yapılır."}], "uygula": "Bugün okuduğun sayfada nûn-i sâkin ve tenvinleri bulup hangi kurala girdiklerini işaretle."}, {"id": "te7", "sev": "Orta", "t": "Mîm-i sâkin kuralları", "dk": 6, "bl": [{"p": "Harekesiz mim (مْ) okunurken sonraki harfe göre üç kural uygulanır."}, {"h": "1. İhfâ-i şefevî"}, {"p": "Sonra ب gelirse mim, dudaklar hafifçe kapanarak gizli ve genizden okunur. Örnek: تَرْمِيهِمْ بِحِجَارَةٍ."}, {"h": "2. İdgâm-ı misleyn"}, {"p": "Sonra yine م gelirse iki mim birleşir, şeddeli ve gunneli okunur. Örnek: لَهُمْ مَا (lehümmâ)."}, {"h": "3. İzhâr-ı şefevî"}, {"p": "Diğer bütün harflerde mim açıkça okunur; özellikle و ve ف harflerinden önce gizlememeye dikkat edilir. Örnek: عَلَيْهِمْ وَلَا."}], "oz": ["Mîm-i sâkinden sonra ب: ihfâ-i şefevî.", "Sonra م: idgâm-ı misleyn.", "Diğer harflerde izhâr-ı şefevî."], "test": [{"s": "Mîm-i sâkinden sonra ب gelirse hangi kural uygulanır?", "c": ["İdgâm-ı misleyn", "İhfâ-i şefevî", "İzhâr-ı şefevî"], "d": 1, "a": "ب gelince ihfâ-i şefevî yapılır."}, {"s": "لَهُمْ مَا nasıl okunur?", "c": ["lehüm mâ (ayrı)", "lehün mâ", "lehümmâ (birleşik, gunneli)"], "d": 2, "a": "Mim mime kavuştuğu için idgâm-ı misleyn olur."}, {"s": "Mîm-i sâkinden sonra و gelirse ne yapılır?", "c": ["Gizlenir", "Açık okunur", "Okunmaz"], "d": 1, "a": "و ve ف'den önce mim açıkça okunur."}], "uygula": "Bugün okuduğun sayfada harekesiz mimleri bul ve hangi kurala girdiklerini işaretle."}]}, {"id": "tefsir", "ad": "Tefsir", "cat": "kuran", "kisa": "Âyetleri anlamak: açıklama, iniş sebebi ve mesaj.", "dersler": [{"id": "tf1", "sev": "Başlangıç", "t": "Tefsir nedir? Fâtiha sûresi", "dk": 6, "bl": [{"p": "Tefsir sözlükte “açmak, açıklamak” demektir. Terim olarak, Kur'an âyetlerinin anlamını, iniş sebeplerini ve verdiği mesajları açıklayan ilimdir. Meal bir tercümedir; tefsir ise açıklamadır."}, {"h": "Fâtiha sûresi"}, {"p": "Kur'an'ın ilk sûresidir ve Mekke'de inmiştir. Yedi âyettir. “Ümmü'l-Kitâb” (Kitabın anası) ve “es-Seb'u'l-mesânî” (sürekli tekrarlanan yedi âyet) gibi adlarla da anılır. Namazın her rekâtında okunur."}, {"q": ["1:2"], "src": "Fâtiha 1/2"}, {"h": "Ana mesajları"}, {"list": ["İlk âyetler: Hamd ve övgü âlemlerin Rabbi, Rahmân ve Rahîm, hesap gününün sahibi olan Allah'adır.", "Ortadaki âyet: Kul, ibadetin ve yardım dilemenin yalnız Allah'a olduğunu söyler.", "Son âyetler: Kul doğru yolu, nimet verilenlerin yolunu ister; sapmışların yolundan uzak durmayı diler."]}, {"p": "Bir kudsî hadiste Allah şöyle buyurur: “Namazı (Fâtiha'yı) kulumla aramda ikiye böldüm. Kulumun istediği kendisine verilecektir.” (Müslim, Salât; Ebû Hüreyre)"}], "oz": ["Tefsir, âyetleri açıklama ilmidir; meal ise tercümedir.", "Fâtiha yedi âyettir, Ümmü'l-Kitâb diye de anılır.", "Fâtiha hamd, kulluk ve doğru yol duasını bir araya getirir."], "test": [{"s": "Tefsir kelimesinin sözlük anlamı nedir?", "c": ["Güzel okumak", "Ezberlemek", "Açmak, açıklamak"], "d": 2, "a": "Tefsir sözlükte açmak, açıklamak demektir."}, {"s": "Fâtiha sûresinin diğer adlarından biri hangisidir?", "c": ["Sûretü'l-Mülk", "Kalbü'l-Kur'ân", "Ümmü'l-Kitâb"], "d": 2, "a": "Fâtiha, Ümmü'l-Kitâb (Kitabın anası) diye de anılır."}, {"s": "Fâtiha kaç âyettir?", "c": ["7", "5", "10"], "d": 0, "a": "Fâtiha yedi âyettir."}, {"s": "“İyyâke na'büdü ve iyyâke neste'în” âyetinin mesajı nedir?", "c": ["Yeryüzünde gezip dolaşmak", "Sabırlı olmak", "İbadet ve yardım dileme yalnız Allah'a"], "d": 2, "a": "Bu âyet kulluğun ve yardım dilemenin yalnız Allah'a olduğunu bildirir."}], "uygula": "Bugün namazda “ihdinâ's-sırâta'l-müstakîm” derken bunun bir dua olduğunu düşünerek oku."}, {"id": "tf3", "sev": "Başlangıç", "t": "Kur'an'ın indirilişi", "dk": 5, "bl": [{"p": "Kur'an, Peygamberimize yaklaşık 23 yılda, olaylara ve ihtiyaçlara göre parça parça indirildi. İnişi Ramazan ayında, Kadir gecesinde başladı."}, {"q": ["97:1"], "src": "Kadr 97/1"}, {"h": "Mekkî ve Medenî sûreler"}, {"list": ["Mekkî sûreler: Hicretten önce inenler. Daha çok iman, tevhid, âhiret ve ahlak konularını işler.", "Medenî sûreler: Hicretten sonra inenler. İbadet, aile, toplum ve hukuk hükümleri ağırlıktadır."]}, {"h": "Kur'an'ın yapısı"}, {"list": ["114 sûre", "30 cüz", "Kûfe sayımına göre 6236 âyet; mushaflarımız bu sayıma göredir"]}], "oz": ["Kur'an yaklaşık 23 yılda indi.", "İnişi Ramazan'da, Kadir gecesinde başladı.", "114 sûre, 30 cüz, 6236 âyet."], "test": [{"s": "Kur'an kaç yılda indirildi?", "c": ["Yaklaşık 10", "Yaklaşık 40", "Yaklaşık 23"], "d": 2, "a": "Kur'an yaklaşık 23 yılda indirildi."}, {"s": "Mekkî sûrelerin ağırlıklı konusu nedir?", "c": ["Savaş hükümleri", "Hukuk ve miras", "İman, tevhid ve âhiret"], "d": 2, "a": "Mekkî sûreler daha çok inanç konularını işler."}, {"s": "Kur'an kaç sûredir?", "c": ["120", "99", "114"], "d": 2, "a": "Kur'an 114 sûredir."}], "uygula": "Bugün Kadr sûresini okuyup anlamını düşün."}, {"id": "tf2", "sev": "Orta", "t": "İhlâs sûresi: Tevhidin özü", "dk": 6, "bl": [{"p": "İhlâs sûresi dört âyettir. Konusu tevhiddir: Allah'ın birliği ve hiçbir şeye benzemezliği. Adı “samimiyet, katıksız inanç” anlamına gelir."}, {"p": "Peygamberimiz bu sûrenin Kur'an'ın üçte birine denk olduğunu bildirmiştir. (Buhârî, Fezâilü'l-Kur'ân; Müslim, Salâtü'l-müsâfirîn)"}, {"q": ["112:1"], "src": "İhlâs 112/1"}, {"h": "Âyet âyet"}, {"list": ["“De ki: O, Allah'tır, bir tektir.” Ehad: eşi, benzeri, parçası olmayan tek.", "“Allah Samed'dir.” Samed: hiçbir şeye muhtaç olmayan, her şeyin kendisine muhtaç olduğu.", "“O doğurmamış ve doğurulmamıştır.” Allah'a çocuk ya da ata nispet eden inanışları reddeder.", "“Hiçbir şey O'na denk değildir.”"]}, {"p": "Rivayete göre müşrikler Peygamberimize “Rabbini bize tanıt” dediklerinde bu sûre inmiştir. (Tirmizî, Tefsîr)"}], "oz": ["İhlâs dört âyettir, konusu tevhiddir.", "Kur'an'ın üçte birine denk olduğu bildirilmiştir.", "Samed: hiçbir şeye muhtaç olmayan, her şeyin O'na muhtaç olduğu."], "test": [{"s": "İhlâs sûresi kaç âyettir?", "c": ["3", "7", "4"], "d": 2, "a": "İhlâs dört âyettir."}, {"s": "“Samed” ne demektir?", "c": ["Her şeyi işiten", "Çok bağışlayan", "Hiçbir şeye muhtaç olmayan, her şeyin O'na muhtaç olduğu"], "d": 2, "a": "Samed, her şeyin kendisine muhtaç olduğu, hiçbir şeye muhtaç olmayandır."}, {"s": "Peygamberimiz İhlâs'ın Kur'an'ın ne kadarına denk olduğunu bildirmiştir?", "c": ["Dörtte birine", "Üçte birine", "Yarısına"], "d": 1, "a": "Buhârî ve Müslim'deki hadise göre Kur'an'ın üçte birine denktir."}, {"s": "Sûrenin ana konusu nedir?", "c": ["Tevhid", "Ahiret", "Peygamber kıssaları"], "d": 0, "a": "İhlâs, Allah'ın birliğini anlatır."}], "uygula": "Bugün İhlâs'ı okurken her âyetin anlamını hatırla ve üç kez okumaya çalış."}, {"id": "tf7", "sev": "Orta", "t": "İniş sebepleri (esbâb-ı nüzûl)", "dk": 6, "bl": [{"p": "Bazı âyetler belirli bir olay ya da soru üzerine inmiştir. Bu olaylara “esbâb-ı nüzûl” (iniş sebepleri) denir. Sebebi bilmek âyetin doğru anlaşılmasına yardım eder."}, {"h": "Bir örnek: Abese sûresi"}, {"p": "Peygamberimiz Mekke'nin ileri gelenlerine İslam'ı anlatırken, gözleri görmeyen sahabi Abdullah b. Ümmi Mektûm gelip bir şey sordu. Peygamberimizin yüzünü ekşitmesi üzerine Abese sûresinin ilk âyetleri indi. (Tirmizî, Tefsîr; Hz. Âişe)"}, {"q": ["80:1", "80:2"], "src": "Abese 80/1-2"}, {"h": "Önemli bir kural"}, {"p": "Tefsir âlimlerinin genel kabulüne göre, âyetin hükmü inişine sebep olan olayla sınırlı değildir; âyetin ifadesi geneldir. Yani âyet, benzer durumlardaki herkese hitap eder."}, {"not": "Peygamberimiz bu olaydan sonra Abdullah b. Ümmi Mektûm'a özel bir ilgi gösterir, onu Medine'de yerine vekil bırakırdı."}], "oz": ["Bazı âyetler bir olay ya da soru üzerine inmiştir.", "Abese sûresi Abdullah b. Ümmi Mektûm olayı üzerine inmiştir.", "Âyetin hükmü sebebiyle sınırlı değildir."], "test": [{"s": "“Esbâb-ı nüzûl” ne demektir?", "c": ["Âyet sayısı", "Sûre isimleri", "Âyetlerin iniş sebepleri"], "d": 2, "a": "İniş sebepleri anlamındadır."}, {"s": "Abese sûresinin başı hangi sahabi ile ilgilidir?", "c": ["Abdullah b. Ümmi Mektûm", "Zeyd b. Hârise", "Bilâl-i Habeşî"], "d": 0, "a": "Gözleri görmeyen sahabi Abdullah b. Ümmi Mektûm ile ilgilidir."}, {"s": "Bir âyetin hükmü sadece iniş sebebindeki olaya mı aittir?", "c": ["Hayır, ifadesi geneldir", "Hükmü kalmamıştır", "Evet, sadece o olaya"], "d": 0, "a": "Âyetin hükmü benzer durumlara da uygulanır."}], "uygula": "Bugün kimseyi dış görünüşüne ya da mevkisine göre ayırmadan aynı ilgiyle dinle."}]}, {"id": "hadis", "ad": "Hadis", "cat": "ilim", "kisa": "Peygamberimizin sözleri, yaşayışı ve hadislerin değerlendirilmesi.", "dersler": [{"id": "hd1", "sev": "Başlangıç", "t": "Hadis nedir? Sünnet ve hadis", "dk": 5, "bl": [{"p": "Hadis, Peygamberimizin sözleri, davranışları ve onayladığı şeylerdir. Onun gördüğü bir davranışa ses çıkarmayarak onaylamasına “takrir” denir. Sünnet ise onun yaşayışı ve yoludur."}, {"p": "Kur'an'dan sonra dinin ikinci temel kaynağı sünnettir. Kur'an şöyle buyurur:"}, {"q": ["59:7"], "src": "Haşr 59/7"}, {"h": "Bir hadisin iki parçası"}, {"list": ["Sened: hadisi nakleden kişilerin zinciri (râviler).", "Metin: Peygamberimizden nakledilen sözün ya da olayın kendisi."]}, {"h": "Kütüb-i Sitte"}, {"p": "En çok başvurulan altı hadis kitabına Kütüb-i Sitte denir: Buhârî, Müslim, Ebû Dâvûd, Tirmizî, Nesâî ve İbn Mâce'nin eserleri."}], "oz": ["Hadis: Peygamberimizin sözü, davranışı ve onayı.", "Sünnet dinin ikinci temel kaynağıdır.", "Hadis sened (râvi zinciri) ve metinden oluşur."], "test": [{"s": "“Takrir” ne demektir?", "c": ["Hadisin yazıya geçirilmesi", "Kur'an'ın ezberlenmesi", "Peygamberimizin bir davranışı görüp ses çıkarmayarak onaylaması"], "d": 2, "a": "Takrir, Peygamberimizin bir davranışa itiraz etmeyip onaylamasıdır."}, {"s": "Hadiste “sened” neyi ifade eder?", "c": ["Hadisi nakleden kişilerin zinciri", "Hadisin anlamı", "Hadisin yazıldığı kitap"], "d": 0, "a": "Sened, hadisin bize ulaştığı râvi zinciridir."}, {"s": "Hangisi Kütüb-i Sitte'den biri değildir?", "c": ["Buhârî", "Riyâzü's-Sâlihîn", "Tirmizî"], "d": 1, "a": "Riyâzü's-Sâlihîn, İmam Nevevî'nin seçme hadislerden derlediği bir eserdir; Kütüb-i Sitte'den biri değildir."}, {"s": "Kur'an'dan sonra dinin ikinci temel kaynağı nedir?", "c": ["Sünnet", "Tarih kitapları", "Gelenekler"], "d": 0, "a": "Sünnet, Kur'an'dan sonra ikinci temel kaynaktır."}], "uygula": "Bugün bir hadis okuyup kaynağını da öğren; Vird'deki günün hadisi iyi bir başlangıç."}, {"id": "hd3", "sev": "Başlangıç", "t": "“Ameller niyetlere göredir” hadisi", "dk": 5, "bl": [{"p": "Bu hadis Buhârî'nin Sahîh'inin ilk hadisidir; İmam Nevevî de meşhur Kırk Hadis'ine bununla başlamıştır."}, {"ar": "إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى", "ok": "İnneme'l-a'mâlü bi'n-niyyât, ve innemâ li-külli'mriin mâ nevâ.", "tr": "Ameller ancak niyetlere göredir; herkese ancak niyet ettiği şey vardır.", "src": "Buhârî, Bed'ü'l-vahy; Müslim, İmâre (Hz. Ömer)"}, {"p": "Hadisin devamında hicret örneği verilir: Allah ve Resulü için hicret edenin hicreti onlaradır; dünyalık ya da evlenmek için hicret edenin hicreti de niyet ettiği şeyedir."}, {"h": "Hadisten çıkan dersler"}, {"list": ["İbadetin değeri niyetin samimiyetiyle ölçülür.", "Güzel bir niyetle yapılan gündelik işler de ibadete dönüşebilir.", "Dışarıdan aynı görünen iki işin değeri niyete göre farklı olabilir."]}], "oz": ["Ameller niyetlere göredir.", "Bu hadis Buhârî'nin ilk hadisidir.", "Güzel niyet gündelik işi de ibadete dönüştürür."], "test": [{"s": "Bu hadis hangi kitabın ilk hadisidir?", "c": ["Sahîh-i Buhârî", "Riyâzü's-Sâlihîn", "Muvatta"], "d": 0, "a": "Buhârî Sahîh'ine bu hadisle başlamıştır."}, {"s": "Hadisi rivayet eden sahabi kimdir?", "c": ["Ebû Hüreyre", "Hz. Ömer", "Hz. Ali"], "d": 1, "a": "Hz. Ömer'den rivayet edilmiştir."}, {"s": "Hadise göre bir amelin değeri neye bağlıdır?", "c": ["Kaç kişinin gördüğüne", "Niyete", "Süresine"], "d": 1, "a": "Ameller niyetlere göredir."}], "uygula": "Bugün yaptığın üç gündelik işe önceden güzel bir niyet ekle."}, {"id": "hd2", "sev": "Orta", "t": "Hadislerin dereceleri: Sahih, hasen, zayıf", "dk": 6, "bl": [{"p": "Hadis âlimleri, bir sözün Peygamberimize gerçekten ait olup olmadığını sened ve metin üzerinden titizlikle incelemiştir."}, {"list": ["Sahih: Senedi baştan sona kesintisiz, râvileri dürüst (adil) ve sağlam hafızalı (zabt sahibi), daha güvenilir rivayetlere aykırı olmayan ve gizli bir kusur taşımayan hadis.", "Hasen: Sahihin şartlarını taşıyan, ancak râvilerinden birinin hafızası biraz daha zayıf olan hadis.", "Zayıf: Bu şartlardan biri ya da birkaçı eksik olan hadis.", "Mevzû: Uydurma söz. Peygamberimize nispet edilemez."]}, {"p": "Peygamberimiz adına yalan söylemenin ağırlığını şöyle bildirmiştir:"}, {"ar": "مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ", "ok": "Men kezebe aleyye müteammiden, felyetebevve' mak'adehû mine'n-nâr.", "tr": "Kim bilerek benim adıma yalan söylerse, cehennemdeki yerine hazırlansın.", "src": "Buhârî, İlim; Müslim, Mukaddime"}, {"not": "Pratik ölçü: Duyduğun bir sözü “hadis” diye paylaşmadan önce kaynağına bak. Kaynağı belli değilse hadis diye yayma."}], "oz": ["Sahih: kesintisiz sened, güvenilir ve sağlam hafızalı râviler.", "Hasen sahihe yakındır; zayıfta şartlar eksiktir.", "Mevzû uydurmadır; Peygamberimize nispet edilemez."], "test": [{"s": "Sahih hadisin şartlarından biri hangisidir?", "c": ["Çok bilinmesi", "Hadisin kısa olması", "Senedin kesintisiz olması"], "d": 2, "a": "Sahih hadiste sened baştan sona kesintisizdir."}, {"s": "“Mevzû” hadis ne demektir?", "c": ["Uydurma söz", "Kudsî hadis", "Çok kişinin rivayet ettiği hadis"], "d": 0, "a": "Mevzû, Peygamberimize ait olmadığı hâlde ona nispet edilen uydurma sözdür."}, {"s": "Kaynağı belli olmayan bir “hadis” duyduğunda ne yapmalısın?", "c": ["Paylaşmadan önce kaynağını araştırmak", "Hemen paylaşmak", "Değiştirerek anlatmak"], "d": 0, "a": "Peygamberimiz adına yanlış bir söz yaymamak için önce kaynağa bakılmalıdır."}], "uygula": "Bugün sana gelen bir dinî mesajın kaynağını kontrol et; kaynağı yoksa paylaşma."}, {"id": "hd7", "sev": "Orta", "t": "Mütevâtir ve âhâd hadis", "dk": 6, "bl": [{"p": "Hadisler, kaç kişi tarafından rivayet edildiğine göre de sınıflandırılır."}, {"h": "Mütevâtir"}, {"p": "Her nesilde, yalan üzerinde birleşmeleri aklen mümkün olmayan kalabalık bir topluluğun rivayet ettiği hadistir. Kesin bilgi ifade eder. Örnek: “Kim bilerek benim adıma yalan söylerse cehennemdeki yerine hazırlansın.”"}, {"h": "Âhâd"}, {"p": "Mütevâtir derecesine ulaşmayan hadislerdir. Râvi sayısına göre üçe ayrılır:"}, {"list": ["Meşhur: Her nesilde en az üç kişinin rivayet ettiği", "Azîz: Her nesilde en az iki kişinin rivayet ettiği", "Garîb: Bir nesilde tek kişinin rivayet ettiği"]}, {"not": "Garîb bir hadis de sahih olabilir. “Ameller niyetlere göredir” hadisi, ilk nesillerde tek râviyle gelen sahih bir hadistir."}], "oz": ["Mütevâtir: yalan üzerinde birleşemeyecek kalabalığın rivayeti.", "Âhâd: meşhur, azîz ve garîb.", "Garîb hadis de sahih olabilir."], "test": [{"s": "Mütevâtir hadis ne ifade eder?", "c": ["Hiçbir şey", "Kesin bilgi", "Sadece tahmin"], "d": 1, "a": "Mütevâtir hadis kesin bilgi ifade eder."}, {"s": "Bir nesilde tek kişinin rivayet ettiği hadise ne denir?", "c": ["Garîb", "Mütevâtir", "Meşhur"], "d": 0, "a": "Tek râvili hadise garîb denir."}, {"s": "Garîb bir hadis sahih olabilir mi?", "c": ["Sadece kudsî ise", "Hayır, asla", "Evet, olabilir"], "d": 2, "a": "“Ameller niyetlere göredir” garîb ve sahih bir hadistir."}], "uygula": "Bugün okuduğun bir hadisin kaynağına ve râvisine bak."}]}, {"id": "akaid", "ad": "Akaid", "cat": "ibadet", "kisa": "İman esasları; Allah'ı, peygamberleri ve âhireti doğru tanımak.", "dersler": [{"id": "ak1", "sev": "Başlangıç", "t": "İmanın esasları", "dk": 6, "bl": [{"p": "Cebrâil aleyhisselâm insan sûretinde gelip Peygamberimize imanı sorduğunda, Peygamberimiz şöyle cevap vermiştir: “Allah'a, meleklerine, kitaplarına, peygamberlerine ve âhiret gününe iman etmen; hayrıyla şerriyle kadere de iman etmendir.” (Müslim, Îmân; Hz. Ömer)"}, {"h": "Altı iman esası"}, {"list": ["Allah'a iman", "Meleklere iman", "Kitaplara iman", "Peygamberlere iman", "Âhiret gününe iman", "Kadere iman: Her şeyin Allah'ın ilmi, dilemesi ve yaratmasıyla olduğuna inanmak"]}, {"q": ["2:285"], "src": "Bakara 2/285"}, {"h": "Âmentü"}, {"ar": "آمَنْتُ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ وَبِالْقَدَرِ خَيْرِهِ وَشَرِّهِ مِنَ اللَّهِ تَعَالَى، وَالْبَعْثُ بَعْدَ الْمَوْتِ حَقٌّ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "ok": "Âmentü billâhi ve melâiketihî ve kütübihî ve rusülihî ve'l-yevmi'l-âhiri ve bi'l-kaderi hayrihî ve şerrihî mina'llâhi teâlâ, ve'l-ba'sü ba'de'l-mevti hakkun, eşhedü en lâ ilâhe illallâh ve eşhedü enne Muhammeden abdühû ve rasûlüh.", "tr": "Allah'a, meleklerine, kitaplarına, peygamberlerine, âhiret gününe, hayrın ve şerrin Allah'ın takdiriyle olduğuna inandım. Öldükten sonra dirilmek haktır. Şahitlik ederim ki Allah'tan başka ilah yoktur ve yine şahitlik ederim ki Muhammed O'nun kulu ve elçisidir.", "src": "Âmentü (iman esaslarının özeti)"}, {"not": "Mâtürîdî âlimlere göre imanın aslı kalple tasdiktir; dil ile ikrar dünyadaki hükümler için gereklidir."}], "oz": ["İman esasları altıdır; Cibrîl hadisinde sayılmıştır.", "Kadere iman: her şeyin Allah'ın ilmi ve takdiriyle olduğuna inanmak.", "Âmentü, iman esaslarının kısa bir özetidir."], "test": [{"s": "İman esasları kaç tanedir?", "c": ["6", "5", "7"], "d": 0, "a": "Cibrîl hadisinde altı iman esası sayılır."}, {"s": "İman esaslarının sayıldığı meşhur Cibrîl hadisi hangi kaynaktadır?", "c": ["Müslim", "Siyer kitapları", "Muvatta"], "d": 0, "a": "Hadis, Müslim'in Îmân bölümündedir."}, {"s": "Kadere iman ne demektir?", "c": ["Geleceği bilmek", "Her şeyin Allah'ın ilmi, dilemesi ve yaratmasıyla olduğuna inanmak", "Hiçbir şey yapmadan beklemek"], "d": 1, "a": "Kadere iman çalışmayı bırakmak değil, her şeyin Allah'ın takdiriyle olduğuna inanmaktır."}], "uygula": "Bugün Âmentü'yü anlamıyla birlikte bir kez oku."}, {"id": "ak3", "sev": "Başlangıç", "t": "Tevhid: Allah'ın birliği", "dk": 5, "bl": [{"p": "Tevhid, Allah'ın zâtında, sıfatlarında ve fiillerinde bir ve tek olduğuna inanmaktır. İslam'ın temeli “Lâ ilâhe illallah” (Allah'tan başka ilah yoktur) cümlesidir."}, {"p": "Tevhidin zıddı şirktir: Allah'a ibadette, yaratmada ya da sıfatlarında bir ortak tanımak."}, {"q": ["31:13"], "src": "Lokmân 31/13"}, {"h": "Günlük hayatta tevhid"}, {"list": ["Duayı yalnız Allah'a yapmak", "Rızkı, şifayı ve başarıyı sebeplere değil, sebepleri yaratan Allah'a bağlamak", "Uğursuzluk, muska ve fal gibi Allah'a güveni zedeleyen inanışlardan uzak durmak"]}], "oz": ["Tevhid: Allah'ın zâtında, sıfatlarında ve fiillerinde tek olması.", "Şirk büyük bir zulümdür.", "Dua ve ibadet yalnız Allah'a yapılır."], "test": [{"s": "Tevhidin zıddı nedir?", "c": ["Şirk", "Sabır", "Tevekkül"], "d": 0, "a": "Allah'a ortak koşmak, yani şirk."}, {"s": "Lokmân 13'e göre şirk nedir?", "c": ["Büyük bir zulüm", "Küçük bir hata", "Bir ibadet"], "d": 0, "a": "“Şüphesiz şirk büyük bir zulümdür.”"}, {"s": "Hangisi tevhide uygun bir davranıştır?", "c": ["Uğursuzluğa inanmak", "Fala inanmak", "Duayı yalnız Allah'a yapmak"], "d": 2, "a": "Dua ve ibadet yalnız Allah'a yapılır."}], "uygula": "Bugün bir işe başlarken “bismillah” de ve sonucu Allah'a bırak."}, {"id": "ak2", "sev": "Orta", "t": "Allah'ın sıfatları: Zâtî ve sübûtî sıfatlar", "dk": 7, "bl": [{"p": "Akaid âlimleri Allah'ın sıfatlarını, O'nu doğru tanımak için gruplara ayırmıştır. Türkiye'de yaygın olan Mâtürîdî anlayışa göre bir sınıflandırma şöyledir."}, {"h": "Zâtî sıfatlar (yalnız Allah'a ait)"}, {"list": ["Vücûd: Var olması", "Kıdem: Varlığının başlangıcı olmaması", "Bekâ: Varlığının sonu olmaması", "Vahdâniyyet: Bir ve tek olması", "Muhâlefetün li'l-havâdis: Yaratılmışların hiçbirine benzememesi", "Kıyâm bi-nefsihî: Varlığının kendinden olması, hiçbir şeye muhtaç olmaması"]}, {"h": "Sübûtî sıfatlar"}, {"list": ["Hayat: Diri olması", "İlim: Her şeyi bilmesi", "Semi': Her şeyi işitmesi", "Basar: Her şeyi görmesi", "İrade: Dilemesi", "Kudret: Her şeye gücünün yetmesi", "Kelâm: Konuşması", "Tekvîn: Yaratması"]}, {"not": "Mâtürîdîler sübûtî sıfatları sekiz sayar; Eş'arîler ise tekvîni ayrı bir sıfat saymaz ve yedi sayar."}, {"q": ["42:11"], "src": "Şûrâ 42/11"}], "oz": ["Zâtî sıfatlar altıdır: Vücûd, Kıdem, Bekâ, Vahdâniyyet, Muhâlefetün li'l-havâdis, Kıyâm bi-nefsihî.", "Mâtürîdîlere göre sübûtî sıfatlar sekizdir.", "“O'nun benzeri hiçbir şey yoktur.”"], "test": [{"s": "Allah'ın varlığının başlangıcı olmamasına ne denir?", "c": ["Bekâ", "Kıdem", "Vücûd"], "d": 1, "a": "Kıdem, varlığının başlangıcı olmamasıdır; Bekâ ise sonu olmamasıdır."}, {"s": "Mâtürîdîlere göre sübûtî sıfatlar kaç tanedir?", "c": ["6", "7", "8"], "d": 2, "a": "Mâtürîdîler tekvîni de sayarak sekiz sübûtî sıfat sayar."}, {"s": "“Tekvîn” sıfatı ne demektir?", "c": ["İşitme", "Konuşma", "Yaratma"], "d": 2, "a": "Tekvîn, yaratma sıfatıdır."}, {"s": "Allah'ın yaratılmışlara benzememesini ifade eden sıfat hangisidir?", "c": ["Muhâlefetün li'l-havâdis", "Vahdâniyyet", "Kıyâm bi-nefsihî"], "d": 0, "a": "Muhâlefetün li'l-havâdis, yaratılmışların hiçbirine benzememesidir."}], "uygula": "Bugün Esmâü'l-Hüsnâ listesinde bu sıfatlarla ilgili isimleri bul: el-Hayy, el-Alîm, es-Semî', el-Basîr, el-Kadîr."}, {"id": "ak7", "sev": "Orta", "t": "Âhirete iman", "dk": 7, "bl": [{"p": "Âhiret, dünya hayatından sonra başlayan ve sonsuza kadar sürecek hayattır. Âhirete iman, insanın her yaptığının karşılığını göreceğine inanmasıdır."}, {"h": "Âhiret hayatının aşamaları"}, {"list": ["Kabir hayatı (berzah): Ölümle kıyamet arasındaki dönem", "Kıyamet: Dünyanın sonu", "Ba's: Ölülerin diriltilmesi", "Haşir: İnsanların bir araya toplanması", "Hesap ve mîzan: Amellerin hesaba çekilip tartılması", "Sırat: Cehennemin üzerinden geçilecek yol", "Cennet ve cehennem: Ebedî mükâfat ve ceza yurtları"]}, {"q": ["99:7", "99:8"], "src": "Zilzâl 99/7-8"}, {"not": "Âhiret inancı, insanın görülmediği yerde bile doğru davranmasının en güçlü sebebidir."}], "oz": ["Âhiret sonsuz hayattır.", "Kabir, kıyamet, ba's, haşir, hesap, mîzan, sırat, cennet ve cehennem.", "Zerre kadar iyilik de kötülük de karşılığını bulur."], "test": [{"s": "Ölümle kıyamet arasındaki döneme ne denir?", "c": ["Mîzan", "Haşir", "Berzah (kabir hayatı)"], "d": 2, "a": "Bu döneme berzah denir."}, {"s": "Amellerin tartılmasına ne denir?", "c": ["Mîzan", "Ba's", "Sırat"], "d": 0, "a": "Amellerin tartılmasına mîzan denir."}, {"s": "Zilzâl 7-8'e göre zerre kadar iyilik yapan ne olur?", "c": ["Karşılığını görür", "Unutulur", "Sadece dünyada görür"], "d": 0, "a": "“Kim zerre ağırlığınca hayır işlerse onu görür.”"}], "uygula": "Bugün kimsenin görmediği küçük bir iyilik yap."}]}, {"id": "ilmihal", "ad": "İlmihal", "cat": "ibadet", "kisa": "Temizlik, namaz, oruç ve günlük ibadetlerin bilgisi.", "dersler": [{"id": "il1", "sev": "Başlangıç", "t": "Abdest: Farzları ve alınışı", "dk": 6, "bl": [{"p": "Abdest namazın şartlarındandır. Abdestin farzları Kur'an'da bildirilmiştir:"}, {"q": ["5:6"], "src": "Mâide 5/6"}, {"h": "Abdestin farzları (Hanefî mezhebine göre)"}, {"list": ["Yüzü bir kez yıkamak", "Kolları dirseklerle birlikte bir kez yıkamak", "Başın dörtte birini meshetmek", "Ayakları topuklarla birlikte bir kez yıkamak"]}, {"not": "Diğer mezheplerde farzların sayısı farklıdır; örneğin Şâfiîlerde niyet ve sıraya uymak da farzdır."}, {"h": "Sünnete uygun alınışı"}, {"list": ["Niyet edip besmele çekilir.", "Eller bileklere kadar yıkanır.", "Ağza üç kez su verilir, burna üç kez su çekilip temizlenir.", "Yüz üç kez yıkanır.", "Önce sağ, sonra sol kol dirseklerle birlikte üç kez yıkanır.", "Baş meshedilir; kulaklar ve boyun meshedilir.", "Önce sağ, sonra sol ayak topuklarla birlikte yıkanır."]}, {"h": "Abdesti bozan bazı durumlar"}, {"list": ["Önden ya da arkadan bir şey çıkması", "Vücudun bir yerinden kan, irin gibi şeylerin akması", "Ağız dolusu kusmak", "Yaslanarak ya da uzanarak uyumak", "Bayılmak", "Namazda yetişkinin sesli gülmesi"]}], "oz": ["Hanefîlere göre abdestin dört farzı vardır.", "Başın dörtte birinin meshi farzdır.", "Abdest sünnete uygun sırayla alınır."], "test": [{"s": "Hanefî mezhebine göre abdestin kaç farzı vardır?", "c": ["6", "4", "3"], "d": 1, "a": "Yüz, kollar, başın dörtte biri ve ayaklar: dört farz."}, {"s": "Başın ne kadarını meshetmek farzdır?", "c": ["Yarısını", "Dörtte birini", "Tamamını"], "d": 1, "a": "Hanefîlere göre başın dörtte birini meshetmek farzdır."}, {"s": "Kollar nasıl yıkanır?", "c": ["Omuzlara kadar", "Bileklere kadar", "Dirseklerle birlikte"], "d": 2, "a": "Kollar dirseklerle birlikte yıkanır."}, {"s": "Hangisi abdesti bozar?", "c": ["Tırnak kesmek", "Ağız dolusu kusmak", "Su içmek"], "d": 1, "a": "Ağız dolusu kusmak abdesti bozar."}], "uygula": "Bugün abdest alırken her adımı sünnete uygun sırayla yapmaya dikkat et."}, {"id": "il3", "sev": "Başlangıç", "t": "Gusül", "dk": 5, "bl": [{"p": "Gusül, bütün bedeni yıkayarak yapılan temizliktir. Cünüplük, kadınlarda hayız ve nifas hâllerinin sona ermesi durumlarında gusletmek farzdır."}, {"q": ["2:222"], "src": "Bakara 2/222"}, {"h": "Guslün farzları (Hanefî mezhebine göre)"}, {"list": ["Ağza su vermek (mazmaza)", "Burna su çekmek (istinşak)", "Bütün bedeni kuru yer kalmayacak şekilde yıkamak"]}, {"not": "Şâfiîlere göre guslün farzları niyet ve bütün bedeni yıkamaktır; ağza ve burna su vermek sünnettir."}, {"h": "Sünnete uygun alınışı"}, {"list": ["Niyet edilip besmele çekilir; eller yıkanır.", "Bedende bir pislik varsa temizlenir.", "Namaz abdesti gibi abdest alınır.", "Önce başa, sonra sağ omuza, sonra sol omuza su dökülerek bütün beden yıkanır."]}], "oz": ["Gusül bütün bedeni yıkamaktır.", "Hanefîlere göre üç farzı vardır: mazmaza, istinşak, bütün bedeni yıkamak.", "Kuru yer kalmamalıdır."], "test": [{"s": "Hanefîlere göre guslün kaç farzı vardır?", "c": ["2", "3", "4"], "d": 1, "a": "Mazmaza, istinşak ve bütün bedeni yıkamak."}, {"s": "Hangisi guslü farz kılan durumlardan biridir?", "c": ["Uyumak", "Tırnak kesmek", "Cünüplük"], "d": 2, "a": "Cünüplük guslü farz kılar."}, {"s": "Gusülde en önemli dikkat nedir?", "c": ["Soğuk su kullanmak", "Bedende kuru yer kalmaması", "Çok su kullanmak"], "d": 1, "a": "Kuru yer kalırsa gusül tamam olmaz."}], "uygula": "Bugün gusül adabını bir kez daha gözden geçir; bilmediğin bir nokta varsa bir hocaya sor."}, {"id": "il2", "sev": "Orta", "t": "Namazın farzları", "dk": 6, "bl": [{"q": ["4:103"], "src": "Nisâ 4/103"}, {"p": "Namazın farzları on ikidir. Altısı namaza başlamadan önce yerine getirilir (şartlar), altısı namazın içindedir (rükünler)."}, {"h": "Namazın dışındaki farzlar (şartlar)"}, {"list": ["Hadesten tahâret: Abdestli olmak, gerekiyorsa gusletmek", "Necâsetten tahâret: Beden, elbise ve namaz kılınan yerin temiz olması", "Setr-i avret: Örtülmesi gereken yerleri örtmek", "İstikbâl-i kıble: Kıbleye yönelmek", "Vakit: Namazı vaktinde kılmak", "Niyet: Hangi namazı kıldığını kalben belirlemek"]}, {"h": "Namazın içindeki farzlar (rükünler)"}, {"list": ["İftitah tekbiri: Namaza başlarken “Allahu ekber” demek", "Kıyam: Ayakta durmak", "Kıraat: Kur'an'dan bir miktar okumak", "Rükû: Eğilmek", "Sücûd: Secde etmek", "Ka'de-i âhire: Son oturuşta teşehhüd miktarı oturmak"]}, {"not": "Farzlardan biri terk edilirse namaz geçersiz olur ve yeniden kılınır. Vaciplerden biri unutulursa sehiv secdesi yapılır."}], "oz": ["Namazın 12 farzı vardır: 6 şart, 6 rükün.", "Şartlar namazdan önce, rükünler namazın içindedir.", "Farz terk edilirse namaz yeniden kılınır; vacip unutulursa sehiv secdesi yapılır."], "test": [{"s": "Namazın kaç farzı vardır?", "c": ["10", "12", "6"], "d": 1, "a": "Altısı dışında (şartlar), altısı içinde (rükünler) olmak üzere on iki."}, {"s": "“İstikbâl-i kıble” ne demektir?", "c": ["Kıbleye yönelmek", "Vakti beklemek", "Niyet etmek"], "d": 0, "a": "İstikbâl-i kıble, namazda kıbleye yönelmektir."}, {"s": "“Ka'de-i âhire” nedir?", "c": ["İlk rekâttaki kıyam", "Namazın sonunda teşehhüd miktarı oturmak", "Secdeden kalkmak"], "d": 1, "a": "Son oturuşta teşehhüd okuyacak kadar oturmak farzdır."}, {"s": "Namazda bir vacip unutulursa ne yapılır?", "c": ["Sehiv secdesi yapılır", "Namaz bozulur", "Hiçbir şey yapılmaz"], "d": 0, "a": "Vacip unutulduğunda sehiv secdesi yapılır."}], "uygula": "Bugün kıldığın bir namazda on iki farzı içinden sırayla hatırla."}, {"id": "il6", "sev": "Orta", "t": "Namazın vacipleri ve sehiv secdesi", "dk": 7, "bl": [{"p": "Vacip, farz kadar kesin olmamakla birlikte yapılması gereken şeydir. Namazda bir vacip unutulursa sehiv (yanılma) secdesi yapılır. (Hanefî mezhebine göre)"}, {"h": "Namazın bazı vacipleri"}, {"list": ["Her rekâtta Fâtiha okumak (farzların son iki rekâtı hariç)", "Farzların ilk iki rekâtında, vitir ve nafilelerin her rekâtında Fâtiha'dan sonra bir sûre ya da âyet okumak", "Rükû ve secdelerde organların yerine oturmasını beklemek (ta'dîl-i erkân)", "Üç ve dört rekâtlı namazlarda ilk oturuş", "Oturuşlarda Et-Tahiyyâtü'yü okumak", "Namazdan selamla çıkmak", "Vitirde kunut duası okumak"]}, {"h": "Sehiv secdesi nasıl yapılır?"}, {"list": ["Son oturuşta Et-Tahiyyâtü okunur.", "Sağa selam verilir.", "İki secde yapılır.", "Oturulup Et-Tahiyyâtü, salli-bârik ve rabbenâ duaları okunur.", "İki tarafa selam verilerek namaz bitirilir."]}, {"not": "Bir farz unutulursa sehiv secdesi yetmez; namaz yeniden kılınır."}], "oz": ["Vacip unutulursa sehiv secdesi yapılır.", "Fâtiha, zamm-ı sûre, ta'dîl-i erkân, ilk oturuş vaciptir.", "Farz unutulursa namaz yeniden kılınır."], "test": [{"s": "Namazda bir vacip unutulursa ne yapılır?", "c": ["Hiçbir şey", "Sehiv secdesi", "Namaz bozulur"], "d": 1, "a": "Vacip unutulursa sehiv secdesi yapılır."}, {"s": "“Ta'dîl-i erkân” ne demektir?", "c": ["Hızlı kılmak", "Rükû ve secdede organların yerine oturmasını beklemek", "Kıbleye dönmek"], "d": 1, "a": "Acele etmeden her rüknü tam yapmaktır."}, {"s": "Sehiv secdesine başlamadan önce ne yapılır?", "c": ["Ayağa kalkılır", "Sağa selam verilir", "Tekbir alınıp kıyama durulur"], "d": 1, "a": "Et-Tahiyyâtü'den sonra sağa selam verilir, sonra iki secde yapılır."}], "uygula": "Bugün namazlarında rükû ve secdede acele etmeden, ta'dîl-i erkâna dikkat et."}]}, {"id": "siyer", "ad": "Siyer", "cat": "ilim", "kisa": "Peygamberimizin hayatı; örnek alınacak bir ömür.", "dersler": [{"id": "sy1", "sev": "Başlangıç", "t": "Peygamberimizin doğumu ve çocukluğu", "dk": 6, "bl": [{"p": "Peygamberimiz Hz. Muhammed (s.a.v.) Mekke'de, Fil Vakası'nın yaşandığı yıl olan 571'de dünyaya geldi. Babası Abdullah, o doğmadan önce vefat etmişti."}, {"list": ["Arap geleneğine göre bir süre çölde, süt annesi Halîme'nin yanında büyüdü.", "Altı yaşındayken annesi Âmine'yi kaybetti.", "Dedesi Abdülmuttalib onu himayesine aldı; sekiz yaşındayken dedesi de vefat etti.", "Bundan sonra amcası Ebû Tâlib ona baktı."]}, {"p": "Gençliğinde dürüstlüğü ve güvenilirliğiyle tanındı; Mekkeliler ona “Muhammedü'l-Emîn” (güvenilir Muhammed) dediler. Yirmi beş yaşında, kendisinden yaşça büyük olan Hz. Hatice ile evlendi."}, {"q": ["93:6"], "src": "Duhâ 93/6"}], "oz": ["571'de Mekke'de doğdu; babası doğumundan önce vefat etti.", "Annesini 6, dedesini 8 yaşında kaybetti; amcası Ebû Tâlib büyüttü.", "Güvenilirliği sebebiyle el-Emîn diye anıldı."], "test": [{"s": "Peygamberimiz nerede doğdu?", "c": ["Mekke", "Medine", "Taif"], "d": 0, "a": "Mekke'de doğdu."}, {"s": "Annesi Âmine'yi kaç yaşında kaybetti?", "c": ["6", "25", "12"], "d": 0, "a": "Altı yaşındayken annesini kaybetti."}, {"s": "Mekkelilerin ona verdiği lakap neydi?", "c": ["es-Sıddîk", "el-Fârûk", "el-Emîn"], "d": 2, "a": "Güvenilirliği sebebiyle “Muhammedü'l-Emîn” denirdi."}, {"s": "Dedesinin vefatından sonra onu kim büyüttü?", "c": ["Amcası Hz. Hamza", "Süt annesi Halîme", "Amcası Ebû Tâlib"], "d": 2, "a": "Amcası Ebû Tâlib onu himayesine aldı."}], "uygula": "Bugün bir yetimi sevindirmeyi ya da yetimlere destek olmayı düşün; Peygamberimiz de bir yetimdi."}, {"id": "sy2", "sev": "Başlangıç", "t": "Peygamberlik ve Mekke yılları", "dk": 7, "bl": [{"p": "Peygamberimiz kırk yaşına yaklaştığında Hira mağarasında tefekküre çekilirdi. 610 yılında burada ilk vahiy geldi: Alak sûresinin ilk âyetleri. (Buhârî, Bed'ü'l-vahy)"}, {"q": ["96:1"], "src": "Alak 96/1"}, {"h": "Mekke dönemi"}, {"list": ["İlk iman edenler: Hz. Hatice, Hz. Ebû Bekir, Hz. Ali ve Zeyd b. Hârise.", "Yaklaşık üç yıl davet gizli yapıldı, sonra açıktan tebliğ başladı.", "Müslümanlar ağır baskı ve işkenceye uğradı; bir grup 615'te Habeşistan'a hicret etti.", "Müslümanlara yaklaşık üç yıl süren bir boykot uygulandı.", "619'da Hz. Hatice ve Ebû Tâlib vefat etti; bu yıla “Hüzün Yılı” denir.", "İsrâ ve Mi'rac'da beş vakit namaz farz kılındı.", "622'de Medine'ye hicret edildi; hicrî takvim bu olayla başlar."]}], "oz": ["İlk vahiy 610'da Hira'da geldi: Alak sûresinin başı.", "Mekke yılları baskı, sabır ve tebliğle geçti.", "622'de Medine'ye hicret edildi; hicrî takvim buradan başlar."], "test": [{"s": "İlk vahiy nerede geldi?", "c": ["Kâbe", "Hira mağarası", "Sevr mağarası"], "d": 1, "a": "İlk vahiy Hira mağarasında geldi."}, {"s": "İlk inen âyetler hangi sûredendir?", "c": ["Alak", "İhlâs", "Fâtiha"], "d": 0, "a": "İlk inen âyetler Alak sûresinin ilk âyetleridir."}, {"s": "Medine'ye hicret hangi yıl oldu?", "c": ["610", "622", "615"], "d": 1, "a": "Hicret 622'de oldu ve hicrî takvimin başlangıcı kabul edildi."}, {"s": "“Hüzün Yılı” hangi kayıplar sebebiyle böyle anılır?", "c": ["Hz. Hamza'nın şehadeti", "Hz. Ebû Bekir'in vefatı", "Hz. Hatice ve Ebû Tâlib'in vefatı"], "d": 2, "a": "619'da Hz. Hatice ve Ebû Tâlib vefat etti."}], "uygula": "Bugün zor bir durumda sabrı hatırla; Mekke yılları sabır ve sebatla geçti."}, {"id": "sy3", "sev": "Orta", "t": "Hicret ve Medine'de kardeşlik", "dk": 6, "bl": [{"p": "622 yılında Peygamberimiz, Hz. Ebû Bekir ile birlikte Mekke'den ayrıldı. Müşrikler peşlerine düşünce üç gün Sevr mağarasında saklandılar."}, {"q": ["9:40"], "src": "Tevbe 9/40"}, {"list": ["Medine'ye varmadan önce Kuba'da, İslam'ın ilk mescidi olan Kuba Mescidi'ni inşa ettiler.", "Medine'de Mescid-i Nebevî yapıldı; burası ibadet, eğitim ve yönetim merkezi oldu.", "Mekke'den gelen muhacirler ile Medineli ensar arasında kardeşlik kuruldu; ensar evlerini ve mallarını kardeşleriyle paylaştı.", "Medine'deki farklı topluluklarla birlikte yaşamayı düzenleyen bir antlaşma (Medine Vesikası) yapıldı."]}], "oz": ["622'de Medine'ye hicret edildi; Sevr mağarasında üç gün kalındı.", "İlk mescid Kuba Mescidi'dir.", "Muhacir ve ensar arasında kardeşlik kuruldu."], "test": [{"s": "Hicret sırasında saklanılan mağara hangisidir?", "c": ["Sevr", "Hira", "Uhud"], "d": 0, "a": "Sevr mağarasında üç gün saklandılar."}, {"s": "İslam'ın ilk mescidi hangisidir?", "c": ["Mescid-i Nebevî", "Mescid-i Aksâ", "Kuba Mescidi"], "d": 2, "a": "Kuba Mescidi ilk mesciddir."}, {"s": "Medineli Müslümanlara ne denir?", "c": ["Muhacir", "Tâbiîn", "Ensar"], "d": 2, "a": "Medineli Müslümanlara ensar (yardımcılar) denir."}], "uygula": "Bugün ihtiyacı olan bir kardeşine ensar gibi elini uzat."}, {"id": "sy4", "sev": "Orta", "t": "Bedir, Uhud ve Hendek", "dk": 6, "bl": [{"h": "Bedir (624)"}, {"p": "Sayıca çok az olan Müslümanlar, Mekkeli müşriklere karşı büyük bir zafer kazandı."}, {"q": ["3:123"], "src": "Âl-i İmrân 3/123"}, {"h": "Uhud (625)"}, {"p": "Başta kazanılan üstünlük, okçuların Peygamberimizin emrine rağmen yerlerini terk etmesiyle kayba dönüştü. Hz. Hamza bu savaşta şehit oldu. Uhud, itaatin ve sabrın önemini gösteren bir derstir."}, {"h": "Hendek (627)"}, {"p": "Büyük bir ordu Medine'yi kuşattı. Selmân-ı Fârisî'nin önerisiyle şehrin etrafına hendek kazıldı; Peygamberimiz de hendek kazanlarla birlikte çalıştı. Kuşatma bir sonuç vermeden kalktı."}], "oz": ["Bedir 624'te kazanılan büyük bir zaferdir.", "Uhud'da okçuların emri terk etmesi kayba yol açtı; Hz. Hamza şehit oldu.", "Hendek'te Selmân-ı Fârisî'nin önerisiyle hendek kazıldı."], "test": [{"s": "Hz. Hamza hangi savaşta şehit oldu?", "c": ["Uhud", "Hendek", "Bedir"], "d": 0, "a": "Hz. Hamza Uhud'da şehit oldu."}, {"s": "Hendek kazma önerisi kime aittir?", "c": ["Hz. Ömer", "Selmân-ı Fârisî", "Hâlid b. Velîd"], "d": 1, "a": "Selmân-ı Fârisî önermiştir."}, {"s": "Uhud'daki kaybın sebeplerinden biri nedir?", "c": ["Su bulunamaması", "Okçuların yerlerini terk etmesi", "Yağmur yağması"], "d": 1, "a": "Okçular emre rağmen yerlerini terk etti."}], "uygula": "Bugün sana verilen bir sorumluluğu sonuna kadar yerine getir; Uhud'un dersini hatırla."}]}, {"id": "ahlak", "ad": "Ahlak", "cat": "hayir", "kisa": "Güzel ahlak: Peygamberimizin örnekliğinde günlük hayat.", "dersler": [{"id": "ah1", "sev": "Başlangıç", "t": "Doğruluk", "dk": 5, "bl": [{"p": "Doğruluk (sıdk), sözün, davranışın ve niyetin birbirine uygun olmasıdır. İslam ahlakının temelidir."}, {"q": ["9:119"], "src": "Tevbe 9/119"}, {"p": "Peygamberimiz şöyle buyurmuştur: “Doğruluk iyiliğe, iyilik de cennete götürür. Yalan kötülüğe, kötülük de cehenneme götürür.” (Buhârî, Edeb; Müslim, Birr; Abdullah b. Mes'ûd)"}, {"p": "Bir başka hadiste münafığın üç alameti sayılır: “Konuştuğunda yalan söyler, söz verdiğinde sözünde durmaz, kendisine bir şey emanet edildiğinde hıyanet eder.” (Buhârî, Îmân; Müslim, Îmân; Ebû Hüreyre)"}, {"h": "Günlük hayatta"}, {"list": ["Şaka da olsa yalan söylememek", "Verdiğin sözü tutmak; tutamayacaksan önceden haber vermek", "Alışverişte ve işte dürüst olmak"]}], "oz": ["Doğruluk; söz, davranış ve niyetin uyumudur.", "Doğruluk iyiliğe, iyilik cennete götürür.", "Yalan, sözünde durmamak ve emanete hıyanet münafıklık alametidir."], "test": [{"s": "“Ve kûnû mea's-sâdıkîn” âyetinin anlamı nedir?", "c": ["Zenginlerle olun", "Doğrularla beraber olun", "Sabredenlerle olun"], "d": 1, "a": "Tevbe 119: “Allah'a karşı gelmekten sakının ve doğrularla beraber olun.”"}, {"s": "Hadise göre doğruluk neye götürür?", "c": ["Zenginliğe", "Şöhrete", "İyiliğe"], "d": 2, "a": "Doğruluk iyiliğe, iyilik de cennete götürür."}, {"s": "Hangisi hadiste sayılan münafık alametlerinden biri değildir?", "c": ["Yalan söylemek", "Az uyumak", "Sözünde durmamak"], "d": 1, "a": "Hadiste yalan, sözünde durmamak ve emanete hıyanet sayılır."}], "uygula": "Bugün verdiğin bir sözü tam vaktinde yerine getir."}, {"id": "ah3", "sev": "Başlangıç", "t": "Anne-baba hakkı", "dk": 5, "bl": [{"q": ["17:23"], "src": "İsrâ 17/23"}, {"p": "Bir adam Peygamberimize “İyi davranmama en layık kimdir?” diye sordu. Peygamberimiz üç kez “Annen” dedi, dördüncüsünde “Sonra baban” buyurdu. (Buhârî, Edeb; Müslim, Birr; Ebû Hüreyre)"}, {"h": "Günlük hayatta"}, {"list": ["Onlara “öf” bile dememek, sesini yükseltmemek", "İhtiyaçlarını sormadan fark edip karşılamak", "Sık sık aramak, ziyaret etmek", "Vefat etmişlerse onlar için dua etmek, sadaka vermek ve akrabalarına iyilik etmek"]}], "oz": ["Allah'a ibadetten sonra anne-babaya iyilik emredilir.", "İyiliğe en layık olan annedir, sonra baba.", "Onlara “öf” bile denmez."], "test": [{"s": "İsrâ 23'e göre anne-babaya ne denmez?", "c": ["Selam verilmez", "“Öf” bile denmez", "Teşekkür edilmez"], "d": 1, "a": "“Onlara öf bile deme.”"}, {"s": "Hadise göre iyiliğe en layık olan kimdir?", "c": ["Komşu", "Kardeş", "Anne"], "d": 2, "a": "Peygamberimiz üç kez “annen” demiştir."}, {"s": "Vefat etmiş anne-baba için ne yapılır?", "c": ["Hiçbir şey", "Dua ve sadaka", "Sadece mezar ziyareti"], "d": 1, "a": "Onlar için dua edilir, sadaka verilir."}], "uygula": "Bugün anneni ya da babanı ara; vefat etmişlerse onlar için Fâtiha oku."}, {"id": "ah2", "sev": "Orta", "t": "Dilin âfetleri: Gıybet ve söz taşımak", "dk": 6, "bl": [{"p": "Peygamberimiz gıybeti şöyle tarif etmiştir: “Kardeşini hoşlanmayacağı bir şeyle anmandır.” “Söylediğim şey onda varsa?” diye sorulunca: “Söylediğin onda varsa gıybet etmiş olursun; yoksa ona iftira etmiş olursun” buyurmuştur. (Müslim, Birr; Ebû Hüreyre)"}, {"q": ["49:12"], "src": "Hucurât 49/12"}, {"p": "Söz taşımak (koğuculuk), insanların arasını bozmak için laf getirip götürmektir. Peygamberimiz “Söz taşıyan cennete giremez” buyurmuştur. (Buhârî, Edeb; Müslim, Îmân; Huzeyfe)"}, {"not": "Âlimler, zulme uğrayanın hakkını aramak için anlatması ya da evlilik, ortaklık gibi bir konuda danışılana dürüst bilgi verilmesi gibi bazı zorunlu durumları gıybetten saymamışlardır."}, {"h": "Korunmak için"}, {"list": ["Gıybet başladığında konuyu güzelce değiştirmek", "Orada olmayan kardeşini savunmak", "Gıybet ettiğin kişi için dua ve istiğfar etmek"]}], "oz": ["Gıybet, kardeşini hoşlanmayacağı bir şeyle anmaktır; doğru değilse iftiradır.", "Kur'an gıybeti ölü kardeşin etini yemeye benzetir.", "Söz taşımak insanlar arasını bozar ve büyük günahtır."], "test": [{"s": "Hadise göre gıybet nedir?", "c": ["Birini yüzüne karşı övmek", "Kardeşini hoşlanmayacağı bir şeyle anmak", "Bir şeyi unutmak"], "d": 1, "a": "Müslim'deki hadiste gıybet böyle tarif edilmiştir."}, {"s": "Söylenen kusur o kişide yoksa bu ne olur?", "c": ["Gıybet", "Nasihat", "İftira"], "d": 2, "a": "Söylenen onda yoksa iftira olur."}, {"s": "Hucurât 12'de gıybet neye benzetilir?", "c": ["Ölü kardeşinin etini yemeye", "Ateşle oynamaya", "Yalan yere yemine"], "d": 0, "a": "Âyet gıybeti ölü kardeşinin etini yemeye benzetir."}, {"s": "Gıybet başladığında ne yapmak güzeldir?", "c": ["Daha fazlasını anlatmak", "Katılmak", "Konuyu güzelce değiştirmek"], "d": 2, "a": "Konuyu değiştirmek ve orada olmayanı savunmak güzel bir davranıştır."}], "uygula": "Bugün bir sohbette biri hakkında olumsuz konuşulursa konuyu güzelce değiştir."}, {"id": "ah10", "sev": "Orta", "t": "Haset, su-i zan ve kalbin temizliği", "dk": 6, "bl": [{"p": "Peygamberimiz şöyle buyurmuştur: “Zandan sakının; çünkü zan sözlerin en yalanıdır. Birbirinizin kusurunu araştırmayın, birbirinize haset etmeyin, birbirinize sırt çevirmeyin; ey Allah'ın kulları, kardeş olun.” (Buhârî, Edeb; Müslim, Birr; Ebû Hüreyre)"}, {"q": ["113:5"], "src": "Felak 113/5"}, {"h": "Haset ve gıpta"}, {"list": ["Haset (kıskançlık): Başkasındaki nimetin ondan gitmesini istemek; kalbi ve iyilikleri tüketir.", "Gıpta (imrenme): Başkasındaki nimetin kendinde de olmasını istemek; nimetin ondan gitmesini istememek. Bu caizdir."]}, {"p": "Peygamberimiz iki kişiye imrenilebileceğini bildirmiştir: Allah'ın verdiği malı hak yolunda harcayan ve Allah'ın verdiği ilimle hükmedip onu öğreten. (Buhârî, İlim; Müslim, Salâtü'l-müsâfirîn; İbn Mes'ûd)"}, {"h": "Kalbi temiz tutmak için"}, {"list": ["Kardeşinin iyiliğini isteyip onun için dua etmek", "Duyduğun şeyi en güzel ihtimale yormak (hüsn-i zan)", "Nimetleri kendi hayatında saymak ve şükretmek"]}], "oz": ["Zan sözlerin en yalanıdır; kusur araştırılmaz.", "Haset nimetin gitmesini istemek, gıpta onun benzerini istemektir.", "Hüsn-i zan ve dua kalbi temizler."], "test": [{"s": "Hadise göre sözlerin en yalanı nedir?", "c": ["Zan", "Övgü", "Şaka"], "d": 0, "a": "“Zan sözlerin en yalanıdır.”"}, {"s": "Haset ile gıpta arasındaki fark nedir?", "c": ["İkisi aynıdır", "Haset nimetin gitmesini, gıpta benzerini istemektir", "Gıpta haramdır"], "d": 1, "a": "Gıpta caiz, haset ise kötüdür."}, {"s": "Hadise göre kime imrenilebilir?", "c": ["En güçlü olana", "Malını hak yolunda harcayana ve ilmini öğretene", "En ünlü olana"], "d": 1, "a": "Buhârî ve Müslim'deki hadiste bu iki kişi sayılır."}], "uygula": "Bugün kıskandığın ya da hakkında kötü düşündüğün biri için samimiyetle dua et."}]}];
